// 根據日期 + 使用者種子 + 卡片 ID 取得當日 variation index
function getDailyVariation(cardId, seed) {
  const today = new Date();
  const dateStr = today.getFullYear() + '-' + (today.getMonth() + 1) + '-' + today.getDate();
  const fullSeed = dateStr + (seed || '') + '_var_' + cardId;
  let hash = 0;
  for (let i = 0; i < fullSeed.length; i++) {
    hash = ((hash << 5) - hash) + fullSeed.charCodeAt(i);
    hash = hash & hash;
  }
  return Math.abs(hash);
}

// 根據日期 + 使用者隨機種子取得當日牌
function getDailyCard(seed) {
  const today = new Date();
  const dateStr = today.getFullYear() + '-' + (today.getMonth() + 1) + '-' + today.getDate();
  const fullSeed = dateStr + (seed || '');
  let hash = 0;
  for (let i = 0; i < fullSeed.length; i++) {
    hash = ((hash << 5) - hash) + fullSeed.charCodeAt(i);
    hash = hash & hash;
  }
  return Math.abs(hash) % 78;
}

function getTodayString() {
  const d = new Date();
  return d.getFullYear() + '/' + (d.getMonth() + 1) + '/' + d.getDate();
}

function getStarRating(n) {
  return '★'.repeat(n) + '☆'.repeat(5 - n);
}

// 從卡片中取出對應 variation
function getFortune(cardId, variationIdx) {
  const card = DAILY_FORTUNES[cardId];
  const idx = (variationIdx !== undefined && variationIdx !== null)
    ? (variationIdx % card.variations.length)
    : 0;
  return { name: card.name, ...card.variations[idx] };
}
